        this.amountInput.set('');
        this.noteInput.set('');
      }
    } catch (e) {
      if (this.session.sheet() !== sheet) return;
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 403
          ? 'Your role may not save claim templates.'
          : 'Could not save this claim template.',
      );
    } finally {
      this.submitting = false;
    }
  }
}

